55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	};
63	
64	/** Rounds to whole G in the MHPCO's favour. */
65	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
66	
67	const quotePremium = (items: Item[]): number => {
68	  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
69	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
70	  return roundUpToWholeG(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
71	};
72	
73	export const runScenario = (scenario: Scenario): ScenarioResult => {
74	  return {
75	    results: scenario.steps.map((step) => ({
76	      premium: quotePremium((step as QuoteStep).items),
77	    })),
78	  };
79	};
